const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const namibia = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017")
        .filter(ee.Filter.eq('country_na', 'Namibia'))
        .geometry();

    const startDay = '02-21';
    const endDay = '02-28';

    const year_2019_start = '2019-' + startDay;
    const year_2019_end = '2019-' + endDay;

    const long_term_start_year = 2003;
    const long_term_end_year = 2017;
    const years = ee.List.sequence(long_term_start_year, long_term_end_year);

    const collection_id = 'MODIS/061/MOD13A1'; // Using 500m 16-day product for better resolution

    // Function to mask clouds and scale NDVI
    function maskAndScale(image) {
        const qa = image.select('SummaryQA');
        // Keep good data (value 0)
        const mask = qa.eq(0);
        return image.select('NDVI').multiply(0.0001).updateMask(mask);
    }

    // 2. Data Acquisition & Processing
    // Get data for 2019
    const collection_2019 = ee.ImageCollection(collection_id)
        .filterDate(year_2019_start, year_2019_end)
        .filterBounds(namibia);

    if (collection_2019.size().getInfo() === 0) {
        console.log("No images found for the 2019 period.");
        console.log("C1");
        return;
    }
    const image_2019 = collection_2019.map(maskAndScale).median().clip(namibia);

    // Get data for the long-term average
    function getYearlyComposite(year) {
        const startDate = ee.Date.fromYMD(year, 1, 1).advance(ee.Date.parse('YYYY-MM-dd', year + '-' + startDay).getRelative('day', 'year'), 'day');
        const endDate = ee.Date.fromYMD(year, 1, 1).advance(ee.Date.parse('YYYY-MM-dd', year + '-' + endDay).getRelative('day', 'year'), 'day');
        const yearlyColl = ee.ImageCollection(collection_id)
            .filterDate(startDate, endDate)
            .filterBounds(namibia);
        return yearlyColl.map(maskAndScale).median();
    }

    const longTermCollection = ee.ImageCollection.fromImages(
        years.map(getYearlyComposite).flatten()
    );

    if (longTermCollection.size().getInfo() === 0) {
        console.log("No images found for the long-term period (2003-2017).");
        console.log("C1");
        return;
    }
    const long_term_image = longTermCollection.mean().clip(namibia);

    // 3. Calculation & Validation
    const scale = 1000;
    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats_2019 = image_2019.reduceRegion({
        reducer: reducer,
        geometry: namibia,
        scale: scale,
        maxPixels: 1e9
    });

    const stats_long_term = long_term_image.reduceRegion({
        reducer: reducer,
        geometry: namibia,
        scale: scale,
        maxPixels: 1e9
    });

    const ndvi_2019 = stats_2019.get('NDVI_mean').getInfo();
    const pixels_2019 = stats_2019.get('NDVI_count').getInfo();

    const ndvi_long_term = stats_long_term.get('NDVI_mean').getInfo();
    const pixels_long_term = stats_long_term.get('NDVI_count').getInfo();

    if (pixels_2019 === 0 || pixels_long_term === 0) {
        console.log(`Valid pixel count for 2019: ${pixels_2019}`);
        console.log(`Valid pixel count for long-term: ${pixels_long_term}`);
        console.log("No valid pixels found after cloud masking for one or both periods.");
        console.log("C2");
        return;
    }

    if (ndvi_2019 === null || ndvi_long_term === null) {
        console.log("Failed to calculate mean NDVI for one or both periods.");
        console.log("C3");
        return;
    }

    // 4. Evidence and Final Answer
    console.log(`Namibia - Feb 21-28 2019 NDVI: ${ndvi_2019.toFixed(4)} (Pixels: ${pixels_2019})`);
    console.log(`Namibia - Feb 21-28 Long-Term (2003-2017) Avg NDVI: ${ndvi_long_term.toFixed(4)} (Pixels: ${pixels_long_term})`);

    if (ndvi_2019 < ndvi_long_term) {
        console.log("2019 NDVI was lower than the long-term average, indicating worse vegetation health.");
        console.log("A");
    } else {
        console.log("2019 NDVI was not worse than the long-term average.");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during GEE initialization or analysis.");
        console.error(e);
        console.log("D");
    }
}

initEE();
